'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Computes the cumulative range of double-precision floating-point strided array elements.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float64Array} x - input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float64Array} y - output array
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {Float64Array} output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0 ] );
* var y = new Float64Array( x.length );
*
* var v = dcurange( 4, x, 2, 1, y, 1, 0 );
* // returns <Float64Array>[ 0.0, 3.0, 4.0, 6.0, 0.0, 0.0, 0.0, 0.0 ]
*/
function dcurange( N, x, strideX, offsetX, y, strideY, offsetY ) {
	var max;
	var min;
	var ix;
	var iy;
	var v;
	var i;

	if ( N <= 0 ) {
		return y;
	}
	ix = offsetX;
	iy = offsetY;

	v = x[ ix ];
	if ( isnan( v ) ) {
		max = v;
		i = 0;
	} else {
		min = v;
		max = v;
		y[ iy ] = 0.0;
		iy += strideY;
		for ( i = 1; i < N; i++ ) {
			ix += strideX;
			v = x[ ix ];
			if ( isnan( v ) ) {
				max = v;
				break;
			}
			if ( v < min ) {
				min = v;
			} else if ( v > max ) {
				max = v;
			}
			y[ iy ] = max - min;
			iy += strideY;
		}
	}
	// Once a `NaN` value has been encountered, the range is `NaN` for all remaining elements:
	if ( isnan( max ) ) {
		for ( ; i < N; i++ ) {
			y[ iy ] = max;
			iy += strideY;
		}
	}
	return y;
}


// EXPORTS //

module.exports = dcurange;
